pub mod locale {
    use super::Locale;
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub enum Key {
        FormatUnavailable,
        Language,
        PreferenceUnavailable,
        UnsupportedPreference,
    }
    impl Key { pub const ALL: &'static [Self] = &[
        Self::FormatUnavailable,
        Self::Language,
        Self::PreferenceUnavailable,
        Self::UnsupportedPreference,
    ]; }
    pub fn text(key: Key, locale: Locale) -> &'static str { match key {
        Key::FormatUnavailable => match locale {
            Locale::Vietnamese => "Không thể định dạng văn bản giao diện.",
            Locale::English => "Interface text could not be formatted.",
        },
        Key::Language => match locale {
            Locale::Vietnamese => "Ngôn ngữ giao diện",
            Locale::English => "Interface language",
        },
        Key::PreferenceUnavailable => match locale {
            Locale::Vietnamese => "Chưa lưu được lựa chọn ngôn ngữ trên thiết bị này.",
            Locale::English => "The language preference is unavailable on this device.",
        },
        Key::UnsupportedPreference => match locale {
            Locale::Vietnamese => "Ngôn ngữ đã lưu chưa được hỗ trợ; đang dùng tiếng Việt.",
            Locale::English => "The saved language is unsupported; Vietnamese is being used.",
        },
    } }
}
